// `cnt_stream_spec.kind`: computed from other streams.
#define CNT_DERIVED 1

// `cnt_stream_spec.storage`: slots of `slab_class`.
#define CNT_SLAB 0

// `cnt_stream_spec.storage`: a ring of `ring_stride_bytes` records holding `ring_seconds` (0 for the default).
#define CNT_RING 1

// `cnt_subscribe_spec.start`: the next commit on a followed stream, nothing earlier.
#define CNT_START_LIVE 0

// `cnt_subscribe_spec.start`: every payload reaching `start_ns` or later, then live.
#define CNT_START_TIME 1

// `cnt_subscribe_spec.start`: after the position saved under `durable_name` (everything when none is), then live.
#define CNT_START_SAVED 2

// `cnt_sub_event.type`: a payload (`item`) at `position`.
