// `cnt_sub_event.type`: catch-up is over at `position`; what follows is live.
#define CNT_SUB_CAUGHT_UP 2

// `cnt_sub_event.type`: an event at `position` that couldn't be read (`reason` says why).
#define CNT_SUB_UNDECODABLE 3

// The most bytes of a reason `cnt_event` carries (NUL included); a longer one is cut.
#define CNT_REASON_MAX 256

// `cnt_location.kind`: no bytes (a header-only payload).
#define CNT_LOCATION_NONE 0

// `cnt_location.kind`: the bytes inline (at most 4096).
#define CNT_LOCATION_INLINE 1

// `cnt_location.kind`: the bytes in a shared memory slot.
#define CNT_LOCATION_SHM 2

// `cnt_location.kind`, only in what the broker hands back: the bytes are in a chunk file or a ring, which this ABI
// doesn't read yet.
#define CNT_LOCATION_OTHER 3

// `cnt_event.type`: a message type this ABI doesn't decode yet (`payload_type` says which): a purge notice, or
// anything newer.
#define CNT_EVENT_OTHER 0

// `cnt_event.type`: a lease is being taken back.
#define CNT_EVENT_LEASE_PREEMPTED 1

// `cnt_event.type`: the voice turn changed.
#define CNT_EVENT_SYSTEM_STATE_CHANGED 2

// `cnt_event.type`: an ingest notice was refused.
#define CNT_EVENT_INGEST_REJECTED 3

// `cnt_event.type`: the broker refused something this session sent one way; `reason` has its message.
#define CNT_EVENT_ERROR 4

// `cnt_event.type`: a job for this worker; `job` is the caller's (`cnt_job_take_lease`, then `cnt_job_free`).
#define CNT_EVENT_DISPATCH_JOB 5

// `cnt_event.type`: outputs of a committed promise no `cnt_promise` holds: `promise_id`, `items` (the caller's, to
// `cnt_items_free`), and `final_part`.
#define CNT_EVENT_PROMISE_FULFILLED 6

// `cnt_event.type`: a committed promise no `cnt_promise` holds failed: `promise_id` and `reason`.
#define CNT_EVENT_PROMISE_FAILED 7

// What a call returned.
typedef enum cnt_status {
  // It worked.
  CNT_OK = 0,
  // An argument was null, not UTF-8, or out of range.
  CNT_INVALID_ARGUMENT = 1,
  // The socket or the operating system failed.
  CNT_IO = 2,
  // The broker refused the request; `cnt_last_broker_code()` says why.
  CNT_BROKER = 3,
  // The broker sent something the protocol doesn't allow.
  CNT_PROTOCOL = 4,
  // No reply within the request timeout.
  CNT_TIMEOUT = 5,
  // The connection is closed.
  CNT_CLOSED = 6,
  // An arena couldn't be mapped or doesn't match its description.
  CNT_ARENA = 7,
  // The slot was reclaimed or reused, or the lease lapsed.
  CNT_STALE = 8,
  // The slot holds the most pins it can.
  CNT_BUSY = 9,
  // No such arena, slot, or ring.
  CNT_NOT_FOUND = 10,
  // The broker didn't grant a lease now; try again later (`cnt_quote` says when).
  CNT_DENIED = 11,
  // A bug: the library panicked. The message says where.
  CNT_PANIC = 99,
} cnt_status;

