typedef struct cnt_promise cnt_promise;

// What a query found. Opaque: made by `cnt_query`, freed by `cnt_query_result_free`.
typedef struct cnt_query_result cnt_query_result;

// A live subscription. Opaque: made by `cnt_subscribe`; `cnt_subscription_free` ends it.
typedef struct cnt_subscription cnt_subscription;

// A granted lease. Opaque: made by `cnt_quote`, ended (and freed) by `cnt_work_lease_commit`,
